/**
 * Shared response shape returned by every deploy endpoint. Mobius,
 * hydra, and wolverine all return at minimum `{id: string}` plus any
 * service-specific fields — this base type captures that contract.
 *
 * Specific clients may narrow via an extending interface (e.g.
 * `DeployedAutomation extends DeployResponse { … }`) when they have
 * fields a caller might want typed precisely; for now each is an alias.
 */
export interface DeployResponse {
    readonly id: string;
    readonly [key: string]: unknown;
}
/**
 * Progress event emitted by `.deploy()` at start, success, and error
 * boundaries. Wired via `DeployConfig.onEvent` — the same callback is
 * propagated through `overrides` into every recursive `dep.deploy()`,
 * so the event stream describes the whole dependency graph in
 * topological order.
 *
 * Each entity emits exactly one of `deploy:success` or `deploy:error`
 * after its `deploy:start`. On error, the event fires before the
 * exception re-throws, so ancestors also see an error for their own
 * scope as it propagates up.
 *
 * `kind` mirrors the runtime `Deployable.kind` discriminator
 * ("automation" | "agent" | "skill" | "flow" | "aspect"). Typed as a
 * plain string here to avoid an upward import from src/deploy.
 */
export type DeployEvent = {
    readonly type: "deploy:start";
    readonly kind: string;
    readonly name?: string;
} | {
    readonly type: "deploy:success";
    readonly kind: string;
    readonly name?: string;
    readonly id: string;
} | {
    readonly type: "deploy:error";
    readonly kind: string;
    readonly name?: string;
    readonly message: string;
} | {
    /**
     * Emitted after a successful update (PUT) when one or more
     * state entries in the state file declare this entity as
     * a forward dep. Those parents are now bound to the just-updated
     * child's previous workflow version; their hashes will flip on
     * their next deploy because the child's source hash changed.
     *
     * Parents in the *current* deploy graph re-PUT automatically (the
     * topological walk handles them). This event surfaces parents NOT
     * in the current graph — typically users who updated a child in
     * one script and need to redeploy parents in another.
     *
     * `child` is the entity that triggered the cascade; `parents` is
     * the list of `(kind, name, id)` tuples found in state.
     */
    readonly type: "deploy:stale-parent";
    readonly child: {
        readonly kind: string;
        readonly name?: string;
        readonly id: string;
    };
    readonly parents: ReadonlyArray<{
        readonly kind: string;
        readonly name: string;
        readonly id: string;
    }>;
};
